'use strict';
const inviteToken=location.hash.slice(1);history.replaceState(null,'','/join');
async function inviteRequest(path,data){const res=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),value=await res.json();if(!res.ok)throw new Error(value.error||'Please try again.');return value;}
const inviteError=error=>{const node=document.querySelector('#join-error');node.textContent=error.message;node.hidden=false;};
(async()=>{try{const info=await inviteRequest('invite-info',{token:inviteToken});document.querySelector('#invite-info').textContent=info.name+' · '+info.email+' · '+info.businesses.join(', ');document.querySelector('#join-form').hidden=false;}catch(error){document.querySelector('#invite-info').textContent='Invitation unavailable';inviteError(error);}})();
document.querySelector('#join-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.target,button=form.querySelector('button');if(form.password.value!==form.confirm.value)return inviteError(new Error('The passwords do not match.'));button.disabled=true;try{const activated=await inviteRequest('activate',{token:inviteToken,password:form.password.value});const signed=await inviteRequest('login',{email:activated.email,password:form.password.value});location.replace(signed.redirect||'/work');}catch(error){inviteError(error);}finally{button.disabled=false;}});
